function esc(s) { return String(s == null ? "" : s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;").replace(/'/g, "&apos;"); }
function localTime(t) { const d = new Date(t); return isNaN(d) ? String(t || "") : d.toLocaleString("en-US", { timeZone: "America/Chicago", month: "short", day: "numeric", hour: "numeric", minute: "2-digit", timeZoneName: "short" }); }
function cotEvent(uid, type, lat, lon, staleMs, inner) {
    const now = new Date(); const t = now.toISOString(); const st = new Date(now.getTime() + staleMs).toISOString();
    return '<?xml version="1.0" standalone="yes"?><event version="2.0" uid="' + esc(uid) + '" type="' + type + '" time="' + t + '" start="' + t + '" stale="' + st + '" how="h-g-i-g-o">' +
        '<point lat="' + Number(lat).toFixed(5) + '" lon="' + Number(lon).toFixed(5) + '" hae="0" ce="9999999" le="9999999"/><detail>' + inner + '</detail></event>';
}
// FEMA National Shelter System -- open shelters in Tennessee
const res = msg.payload;
if (!res || !Array.isArray(res.features)) { node.status({ fill: "red", shape: "ring", text: "bad shelter response (HTTP " + msg.statusCode + ")" }); return null; }
const ICON = "f8f7f666-8b28-4b57-9fbb-e48e61d33b79/Iron Sites/Emergency Shelter.png";
const out = []; let pop = 0;
res.features.forEach(function (f) {
    const a = f.attributes || {}, g = f.geometry || {};
    const lat = Number(a.latitude != null ? a.latitude : g.y), lon = Number(a.longitude != null ? a.longitude : g.x);
    if (!isFinite(lat) || !isFinite(lon)) { return; }
    const status = String(a.shelter_status || "").toUpperCase();
    if (status === "CLOSED") { return; }
    pop += Number(a.total_population) || 0;
    const cap = [a.evacuation_capacity ? "Evac cap " + a.evacuation_capacity : "", a.post_impact_capacity ? "Post-impact cap " + a.post_impact_capacity : ""].filter(Boolean).join(", ");
    const remarks = [
        "Shelter " + (status || "STATUS UNKNOWN"),
        a.org_name || "",
        [a.address, a.city, a.state, a.zip].filter(Boolean).join(", "),
        "Population " + (a.total_population != null ? a.total_population : "?") + (cap ? " (" + cap + ")" : ""),
        a.pet_accommodations_code ? "Pets: " + a.pet_accommodations_code : "",
        (a.ada_compliant ? "ADA: " + a.ada_compliant : "") + (a.wheelchair_accessible ? " / Wheelchair: " + a.wheelchair_accessible : ""),
        (a.hours_open || a.hours_close) ? "Hours: " + (a.hours_open || "?") + "-" + (a.hours_close || "?") : "",
        "FEMA National Shelter System"
    ].filter(function (s) { return s && String(s).trim(); }).join(" | ");
    out.push({ payload: cotEvent("SHELTER-" + (a.shelter_id || a.objectid), "a-f-G", lat, lon, 20 * 60 * 1000,
        '<contact callsign="' + esc(a.shelter_name || "Shelter") + '"/>' +
        '<usericon iconsetpath="' + esc(ICON) + '"/>' +
        '<remarks>' + esc(remarks) + '</remarks>') });
});
node.status({ fill: out.length ? "green" : "grey", shape: "dot", text: out.length ? out.length + " open shelters in TN, " + pop + " occupants" : "no open shelters in TN" });
return [out];
